effect.shader:
float ruido(vec2 p) {
    return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453);
}

vec2 jitter(float t) {
    float a = ruido(vec2(t * frequency, seed)) * 6.28318;
    float r = ruido(vec2(seed, t * frequency)) * amplitude;
    return vec2(cos(a), sin(a)) * r;
}

void main() {
    vec4 original = texture(inputImg, acScreenNorm);
    if (amplitude <= 0.0 && blurAmount <= 0.0) { fragColor = original; return; }

    int n = clamp(int(samples), 2, 32);
    vec2 offset = jitter(acTime);
    vec2 direcao = normalize(offset + vec2(1e-5, 0.0));

    vec4 soma = vec4(0.0);
    float peso = 0.0;
    for (int i = 0; i <= 32; i++) {
        if (i > n) break;
        float t = float(i) / float(n) - 0.5;
        vec2 uv = acScreenNorm + offset + direcao * blurAmount * t;
        soma += texture(inputImg, uv);
        peso += 1.0;
    }
    fragColor = soma / peso;
}
